                total,0.00
                """, csv);
    }

    @Test
    void tourismTaxCharges450PerGuestPerNightFromPaidReservationsStartingInTheMonth() {
        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 4));

        // reservation 1: 1 guest × 2 nights = 9.00
        // reservation 3: 1 guest × 2 nights = 9.00
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-04
                reservation,room,check_in,check_out,guests,nights,tax
                1,201,2027-04-01,2027-04-03,1,2,9.00
                3,301,2027-04-02,2027-04-04,1,2,9.00
                total,18.00
                """, csv);
    }

    @Test
    void tourismTaxIsCalculatedPerGuestAndPerNight() {
        Reservation may = book(102, "2027-05-10", "2027-05-13", RatePlan.STANDARD);
        service.confirm(may.id());

        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 5));

        // 2 guests (from room 102) × 3 nights = 27.00
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-05
                reservation,room,check_in,check_out,guests,nights,tax
                6,102,2027-05-10,2027-05-13,2,3,27.00
                total,27.00
                """, csv);
    }

    @Test
    void ratePlansShowsRevenueGroupedByPlan() {
        String csv = new RatePlansReport(store).generate(YearMonth.of(2027, 4));

        // STANDARD: reservations 1 and 3 (779.80 + 1159.80)
        // NON_REFUNDABLE: none
        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-04
                rate_plan,reservations,amount
                STANDARD,2,1939.60
                NON_REFUNDABLE,0,0.00
                total,2,1939.60
                """, csv);
    }

    @Test
    void ratePlansIncludesBothPlansEvenWhenOneIsEmpty() {
        Reservation may = book(101, "2027-05-10", "2027-05-11", RatePlan.NON_REFUNDABLE);
        service.confirm(may.id());

        String csv = new RatePlansReport(store).generate(YearMonth.of(2027, 5));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-05
                rate_plan,reservations,amount
                STANDARD,0,0.00
                NON_REFUNDABLE,1,212.42
                total,1,212.42
                """, csv);
    }
}

